begin read only;
select '318473c0-46ea-55e7-ab06-53520ea2373f public mapping' check_name,((select count(*) from jsonb_array_elements(math_private.release_catalog('3643b295-3b63-5b77-bd1b-d3ce68de4885')) x where x->>'leaf_id'='edb40a2a-9f42-5170-8e8a-ea1c7c696669' and x->>'essay_question_id'='318473c0-46ea-55e7-ab06-53520ea2373f')=1) passed
union all
select '318473c0-46ea-55e7-ab06-53520ea2373f profile' check_name,((with candidates as(select ep.id,case ep.scope when 'LEAF' then 4 when 'PROBLEM' then 3 when 'EXAM' then 2 else 1 end rank from public.math_subproblems l join public.math_problems pr on pr.id=l.problem_id join public.math_problem_sets ps on ps.id=pr.problem_set_id join public.math_evaluation_profiles ep on ep.state='ACTIVE' and ep.response_format=l.response_format and (ep.leaf_id=l.id or ep.problem_id=l.problem_id or ep.essay_exam_id=ps.essay_exam_id or (ep.scope='COMMON_MATH_RUBRIC' and l.allow_common_rubric)) where l.id='edb40a2a-9f42-5170-8e8a-ea1c7c696669' and pr.state='ACTIVE' and ps.state='ACTIVE') select count(*)=1 and bool_and(id='bcac9c02-5f6b-5fdf-8f1e-7efda9cf44b3'::uuid) from candidates where rank=(select max(rank) from candidates))) passed
union all
select '318473c0-46ea-55e7-ab06-53520ea2373f Worker evidence' check_name,(exists(select 1 from public.math_subproblems l join public.math_problems pr on pr.id=l.problem_id where l.id='edb40a2a-9f42-5170-8e8a-ea1c7c696669' and jsonb_array_length(math_private.hanyang_worker_references(jsonb_build_object('leaf',to_jsonb(l),'problem',to_jsonb(pr),'sources',(select jsonb_agg(to_jsonb(s)) from public.math_source_artifacts s where s.problem_id=pr.id)))->'official_images')>0)) passed
union all
